using System.Text;

namespace StrataLint.ArchitectureTests;

internal static class RepositoryInputClosureArtifact
{
    internal const string RelativeDirectory =
        "Meta/StrataLint/StrataLint.ArchitectureTests/InputClosures/Derived";
    private const string Header =
        "# GENERATED by RepositoryInputClosureDeriver. Do not edit by hand; change loader declarations or calls and regenerate.\n"
        + "project\tsource\ttest\teffects\n";

    internal static IReadOnlyDictionary<string, string> Render(
        RepositoryInputClosureResult result)
    {
        var files = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var project in result.GroupBy(static effect => effect.Project, StringComparer.Ordinal))
        {
            var ordered = project.OrderBy(static effect => effect.SourcePath, StringComparer.Ordinal)
                .ThenBy(static effect => effect.Method, StringComparer.Ordinal)
                .ToArray();
            for (var offset = 0; offset < ordered.Length; offset += 700)
            {
                var part = offset / 700 + 1;
                var builder = new StringBuilder(Header);
                foreach (var effect in ordered.Skip(offset).Take(700))
                {
                    builder.Append(effect.Project).Append('\t')
                        .Append(effect.SourcePath).Append('\t')
                        .Append(effect.Method).Append('\t')
                        .AppendJoin(',', effect.Patterns).Append('\n');
                }

                files[$"{project.Key}.part-{part:D2}.tsv"] = builder.ToString();
            }
        }

        return files;
    }

    internal static void Write(string repositoryRoot, IReadOnlyDictionary<string, string> files)
    {
        var directory = Path.Combine(repositoryRoot, RelativeDirectory);
        Directory.CreateDirectory(directory);
        foreach (var path in Directory.EnumerateFiles(directory, "*.tsv"))
        {
            File.Delete(path);
        }
        foreach (var (name, content) in files)
        {
            File.WriteAllText(Path.Combine(directory, name), content, new UTF8Encoding(false));
        }
    }
}
